(window.PN_ASSISTANT_PACKS = window.PN_ASSISTANT_PACKS || {})["pn-digital"] = {"id":"pn-digital","status":"client","enabled":true,"languages":["en","el"],"endpoint":"https://pn-digital-assistant.tsiopou3.workers.dev/chat","assistant":{"name":{"en":"P&N Digital assistant","el":"Βοηθός P&N Digital"},"tone":"Warm, clear and professional. Short paragraphs. Helpful, never pushy. Explain technical words simply.","welcome":{"en":"Hi! I can explain what P&N Digital builds, what it costs and how a project works, or help you plan a website for your business.","el":"Γεια σας! Μπορώ να σας εξηγήσω τι φτιάχνει η P&N Digital, πόσο κοστίζει και πώς εξελίσσεται ένα έργο, ή να σας βοηθήσω να σχεδιάσετε μια ιστοσελίδα για την επιχείρησή σας."},"suggestions":{"en":["Plan my website","How much does a website cost?","How does the process work?","Can my site be in other languages?"],"el":["Σχεδιάστε την ιστοσελίδα μου","Πόσο κοστίζει μια ιστοσελίδα;","Πώς λειτουργεί η διαδικασία;","Μπορεί η ιστοσελίδα μου να είναι σε άλλες γλώσσες;"]},"guidedFlow":"website-plan","liveNote":{"en":"AI answers can be wrong. Please don’t share personal or sensitive information. This assistant uses Google’s Gemini service, and Google may keep messages to improve its services. P&N Digital does not store your chat.","el":"Οι απαντήσεις AI μπορεί να περιέχουν λάθη. Μη μοιράζεστε προσωπικές ή ευαίσθητες πληροφορίες. Ο βοηθός χρησιμοποιεί την υπηρεσία Gemini της Google και η Google μπορεί να κρατά τα μηνύματα για να βελτιώνει τις υπηρεσίες της. Η P&N Digital δεν αποθηκεύει τη συνομιλία σας."}},"branding":{"accent":"#3cc4c0","onAccent":"#101315","surface":"#14181a","text":"#f3eee3","muted":"#a9afb3","line":"#2a2f33","font":"system-ui, -apple-system, \"Segoe UI\", sans-serif","position":"right"},"contactFallback":{"en":"For anything I cannot answer, message P&N Digital on WhatsApp (+357 94426190), email pndigitalwebsites@gmail.com, or use the contact page: /contact/","el":"Για ό,τι δεν μπορώ να απαντήσω, στείλτε μήνυμα στην P&N Digital στο WhatsApp (+357 94426190), γράψτε στο pndigitalwebsites@gmail.com ή χρησιμοποιήστε τη σελίδα επικοινωνίας: /el/contact/"},"knowledge":{"about":"P&N Digital is an independently operated web design business based in Cyprus, run by one person. It designs and builds fast, responsive websites for small and medium-sized businesses. Clients work directly with the person building their website, from the first conversation to launch.","services":["Custom website design","Website development (fast static websites)","Responsive mobile design","Business landing pages","Restaurant and booking-style experiences (menus, galleries, enquiry or table-request flows; no fake bookings)","Website redesigns","Website maintenance","Basic SEO setup (page titles, headings, sitemap, local details)","Websites in Greek, English or both","Multilingual websites in any language, including right-to-left languages"],"pricing":{"note":"Provisional starting prices in EUR, not fixed quotes. The final price depends on the agreed scope. Domain registration, hosting and third-party services may cost extra. Revisions and support are agreed per project; nothing is unlimited unless agreed in writing.","packages":[{"name":"Starter","price":{"en":"€250","el":"€250"},"for":"A professional basic website","includes":["Up to 2 languages of your choice","Responsive mobile and desktop design","Essential business information","Contact details and links","Basic SEO setup","Essential website sections"]},{"name":"Business","price":{"en":"€450","el":"€450"},"for":"Businesses that need several pages","includes":["Everything in Starter","Up to 3 languages of your choice","Multiple pages","More advanced design and layouts","Services or product presentation","Additional custom sections","Enhanced SEO","More advanced interactions"]},{"name":"Premium","price":{"en":"from €750","el":"από €750"},"for":"Custom design and more advanced functionality","includes":["Up to 5 languages of your choice","Custom website design","More advanced functionality","Custom layouts","Complex interactions","Additional features and integrations where agreed"]},{"name":"Maintenance","price":{"en":"€50 per month","el":"€50 τον μήνα"},"for":"Ongoing care","includes":["Updates in every language on the site","Routine website checks","Minor content updates","Basic technical maintenance","General website support"]}],"languages":"Language guarantee: P&N Digital builds websites in any language the client needs, including right-to-left languages such as Hebrew and Arabic. Included: Starter up to 2 languages, Business up to 3, Premium up to 5, all chosen by the client. More languages can be added to any package and are quoted separately (no fixed price is published). Each language gets its own pages, menus and buttons (not an automatic translation plugin), search engine setup per language, a language switcher on every page, and translations reviewed with the client before launch. If the site has an AI assistant, it replies in the visitor’s language."},"process":["Initial conversation about the business, its customers and what the site should do","Understanding the business: confirm verified details and list what is missing","Planning and design: agree direction, scope and price, then design","Development: a fast, responsive site tested at real screen sizes","Review and refinements: the client reviews every page; agreed changes are made","Launch and handover: agree how the site goes live and explain how to keep it up to date"],"faqs":[{"q":{"en":"Who is behind P&N Digital?","el":"Ποιος βρίσκεται πίσω από την P&N Digital;"},"a":{"en":"P&N Digital is an independently operated web design business based in Cyprus, run by one person. You work directly with the person building your website.","el":"Η P&N Digital είναι μια ανεξάρτητη επιχείρηση σχεδιασμού ιστοσελίδων με έδρα την Κύπρο, που λειτουργεί από ένα άτομο. Συνεργάζεστε απευθείας με το άτομο που φτιάχνει την ιστοσελίδα σας."},"keywords":["who","behind","person","team","about","ποιος","ατομο","ομαδα","σχετικα"]},{"q":{"en":"How much does a website cost?","el":"Πόσο κοστίζει μια ιστοσελίδα;"},"a":{"en":"Provisional starting prices: Starter €250, Business €450, Premium from €750, and Maintenance €50 a month. The final price depends on the scope we agree, and domain, hosting and third-party services may cost extra.","el":"Ενδεικτικές τιμές εκκίνησης: Starter €250, Business €450, Premium από €750 και Συντήρηση €50 τον μήνα. Η τελική τιμή εξαρτάται από το πλαίσιο εργασιών που θα συμφωνήσουμε και το domain, η φιλοξενία και οι υπηρεσίες τρίτων μπορεί να έχουν πρόσθετο κόστος."},"keywords":["cost","price","prices","pricing","how much","package","starter","business","premium","euro","κοστιζει","κοστος","τιμη","τιμες","ποσο","πακετο"],"link":"/#pricing"},{"q":{"en":"How does the process work?","el":"Πώς λειτουργεί η διαδικασία;"},"a":{"en":"Six steps: an initial conversation, understanding your business, planning and design (scope and price agreed first), development, your review and refinements, then launch and handover.","el":"Έξι βήματα: αρχική συζήτηση, κατανόηση της επιχείρησής σας, σχεδιασμός (πρώτα συμφωνούμε πλαίσιο και τιμή), ανάπτυξη, αναθεώρηση και βελτιώσεις, και τέλος έναρξη λειτουργίας και παράδοση."},"keywords":["process","steps","how does","work with","start","διαδικασια","βηματα","πως λειτουργει","ξεκινα"]},{"q":{"en":"Can my website be in other languages?","el":"Μπορεί η ιστοσελίδα μου να είναι και σε άλλες γλώσσες;"},"a":{"en":"Yes, in any language your customers speak, including right-to-left languages such as Hebrew and Arabic. Starter includes up to 2 languages, Business up to 3 and Premium up to 5, all of your choosing; more can be added and are quoted separately. Each language gets its own pages and search engine setup, and translations are reviewed with you before launch.","el":"Ναι, σε όποια γλώσσα μιλούν οι πελάτες σας, ακόμη και σε γλώσσες που γράφονται από δεξιά προς τα αριστερά, όπως τα εβραϊκά και τα αραβικά. Το Starter περιλαμβάνει έως 2 γλώσσες, το Business έως 3 και το Premium έως 5, όποιες επιλέξετε· περισσότερες μπορούν να προστεθούν και τιμολογούνται ξεχωριστά. Κάθε γλώσσα έχει τις δικές της σελίδες και ρύθμιση για τις μηχανές αναζήτησης, και οι μεταφράσεις ελέγχονται μαζί σας πριν από τη δημοσίευση."},"keywords":["greek","english","language","languages","bilingual","multilingual","translation","translate","russian","ukrainian","hebrew","arabic","turkish","german","french","chinese","ελληνικα","αγγλικα","γλωσσα","γλωσσεσ","γλωσσων","διγλωσση","πολυγλωσσ","μεταφρασ","ρωσικα","ουκρανικα","εβραικα","αραβικα","τουρκικα","γερμανικα","γαλλικα","κινεζικα"],"link":"/services/#languages"},{"q":{"en":"Will my website work on phones?","el":"Θα λειτουργεί η ιστοσελίδα μου στα κινητά;"},"a":{"en":"Yes. Every site is designed for phones first and tested at phone, tablet and desktop sizes.","el":"Ναι. Κάθε ιστοσελίδα σχεδιάζεται πρώτα για κινητά και δοκιμάζεται σε μεγέθη κινητού, tablet και υπολογιστή."},"keywords":["phone","mobile","responsive","tablet","κινητο","κινητα","responsive"]},{"q":{"en":"Do I need to buy a domain? Who handles hosting?","el":"Χρειάζεται να αγοράσω domain; Ποιος αναλαμβάνει τη φιλοξενία;"},"a":{"en":"Usually you need your own domain name, and hosting may have its own cost. These are explained and agreed before anything is bought, and nothing is bought without your approval.","el":"Συνήθως χρειάζεστε δικό σας domain και η φιλοξενία μπορεί να έχει δικό της κόστος. Αυτά εξηγούνται και συμφωνούνται πριν αγοραστεί οτιδήποτε και τίποτα δεν αγοράζεται χωρίς την έγκρισή σας."},"keywords":["domain","hosting","host","server","own","φιλοξενια","domain","ιδιοκτησια"]},{"q":{"en":"Can you redesign my existing website?","el":"Μπορείτε να ανανεώσετε την υπάρχουσα ιστοσελίδα μου;"},"a":{"en":"Yes. A redesign gives an outdated site a new design and structure while keeping the content that still works.","el":"Ναι. Η ανανέωση δίνει σε μια παλιά ιστοσελίδα νέο σχεδιασμό και δομή, διατηρώντας το περιεχόμενο που εξακολουθεί να λειτουργεί."},"keywords":["redesign","existing","old","outdated","update","ανανεωση","υπαρχουσα","παλια"]},{"q":{"en":"Do you offer maintenance?","el":"Προσφέρετε συντήρηση;"},"a":{"en":"Yes: Maintenance starts at €50 a month and covers routine checks, minor content updates, basic technical maintenance and general support. Details are agreed for each site.","el":"Ναι: η Συντήρηση ξεκινά από €50 τον μήνα και περιλαμβάνει τακτικούς ελέγχους, μικρές ενημερώσεις περιεχομένου, βασική τεχνική συντήρηση και γενική υποστήριξη. Οι λεπτομέρειες συμφωνούνται για κάθε ιστοσελίδα."},"keywords":["maintenance","support","after launch","updates","συντηρηση","υποστηριξη","ενημερωσεις"]},{"q":{"en":"How long does a website take?","el":"Πόσο χρόνο χρειάζεται μια ιστοσελίδα;"},"a":{"en":"It depends on the scope. The timeline is agreed with you before work starts; I can’t promise a fixed time here.","el":"Εξαρτάται από το πλαίσιο εργασιών. Το χρονοδιάγραμμα συμφωνείται μαζί σας πριν ξεκινήσει η δουλειά· δεν μπορώ να υποσχεθώ συγκεκριμένο χρόνο εδώ."},"keywords":["how long","time","timeline","weeks","fast","ποσο χρονο","χρονος","χρονοδιαγραμμα","εβδομαδες"]},{"q":{"en":"Can I see examples first?","el":"Μπορώ να δω πρώτα παραδείγματα;"},"a":{"en":"Yes. The Work page has five fictional concept websites (a restaurant, a barbershop, a consultancy, a seaside hotel and a beauty salon) you can preview at desktop or phone size.","el":"Ναι. Η σελίδα «Έργα» έχει πέντε φανταστικές πρότυπες ιστοσελίδες (εστιατόριο, κουρείο, εταιρεία συμβούλων, παραθαλάσσιο ξενοδοχείο και σαλόνι ομορφιάς) που μπορείτε να δείτε σε μέγεθος υπολογιστή ή κινητού."},"keywords":["example","examples","portfolio","demo","work","see","παραδειγματα","εργα","δειγμα"],"link":"/work/"},{"q":{"en":"How do I contact you?","el":"Πώς επικοινωνώ μαζί σας;"},"a":{"en":"The quickest way is WhatsApp on +357 94426190. You can also email pndigitalwebsites@gmail.com, call the same number, or fill in the form on the contact page, which opens WhatsApp or email with your message ready.","el":"Ο πιο γρήγορος τρόπος είναι το WhatsApp στο +357 94426190. Μπορείτε επίσης να γράψετε στο pndigitalwebsites@gmail.com, να καλέσετε στον ίδιο αριθμό ή να συμπληρώσετε τη φόρμα στη σελίδα επικοινωνίας, που ανοίγει το WhatsApp ή το email με το μήνυμά σας έτοιμο."},"keywords":["contact","email","phone","call","reach","quote","επικοινωνια","τηλεφωνο","προσφορα","whatsapp","number","επικοινων","τηλεφων","αριθμ"],"link":"/contact/"},{"q":{"en":"Can I get a price estimate?","el":"Μπορώ να έχω μια εκτίμηση τιμής;"},"a":{"en":"Yes. The quote calculator on the Services page shows which package fits and its starting price as you pick pages, languages and extras. You can then send the estimate on WhatsApp or by email. It is a provisional starting price, not a quote.","el":"Ναι. Ο υπολογισμός κόστους στη σελίδα Υπηρεσίες δείχνει ποιο πακέτο ταιριάζει και την τιμή εκκίνησής του καθώς επιλέγετε σελίδες, γλώσσες και επιπλέον. Μετά μπορείτε να στείλετε την εκτίμηση μέσω WhatsApp ή email. Είναι ενδεικτική τιμή εκκίνησης και όχι προσφορά."},"link":"/services/#quote","keywords":["estimate","calculator","calculate","quote","εκτιμηση","υπολογισ","προσφορα"]}],"portfolio":"Five fictional concept websites can be explored on the Work page: Olive & Oak (restaurant), THE CUT (barbershop), Nexora Business Solutions (consultancy), Halcyon Bay (seaside hotel) and Myrtle Beauty Studio (beauty salon). They are demonstrations, not clients."}};
